import { setContext, getContext } from "svelte";
import type { Props } from "./index.js";

const CONTEXT_ID = "accordion-context";
const ITEM_CONTEXT_ID = "accordion-item-context";

class UseCompCtx {
	/** Values of the open items; replaced on every change so bindings update */
	value: string[] = $state.raw([]);
	/** Unique prefix that links each trigger to its content by id */
	baseId = $state("");
	/** Whether several items can be open at once */
	multiple = $state(false);
	/** Whether every item is disabled */
	disabled = $state(false);
	/** Visual style of the accordion */
	variant: NonNullable<Props["variant"]> = $state("default");
	/** Padding and text size of the items */
	size: UiSize = $state("md");
	/** Corner radius override; follows `size` when undefined */
	rounded?: UiRounded = $state();
	/** Called with the open values when an item opens or closes */
	onValueChange?: Props["onValueChange"];

	// Set default data
	constructor(props: { [key: string]: any }) {
		// Merge props into this instance (we do not use `Object.assign(this, props)` to ensure only setting props that exists)
		for (const [key, data] of Object.entries(props)) {
			// @ts-ignore
			if (this[key] !== undefined) this[key] = data;
		}
	}

	/** Whether the item with this value is open. */
	isOpen(value: string) {
		return this.value.includes(value);
	}

	/** Opens or closes an item and reports the change; opening closes the others unless `multiple` is set. */
	toggle(value: string) {
		// If the item is open: close it; otherwise open it beside or instead of the others.
		if (this.isOpen(value)) this.value = this.value.filter((openValue) => openValue !== value);
		else this.value = this.multiple ? [...this.value, value] : [value];
		this.onValueChange?.(this.value);
	}

	/** Builds the trigger id for an item value; whitespace is not allowed in ids. */
	triggerId(value: string) {
		return `${this.baseId}-trigger-${value.replace(/\s+/g, "-")}`;
	}

	/** Builds the content id for an item value; whitespace is not allowed in ids. */
	contentId(value: string) {
		return `${this.baseId}-content-${value.replace(/\s+/g, "-")}`;
	}
}

class UseItemCtx {
	/** Value that identifies the item in the accordion's open values */
	value = $state("");
	/** Whether the item is disabled */
	disabled = $state(false);

	// Set default data
	constructor(props: { [key: string]: any }) {
		// Merge props into this instance (we do not use `Object.assign(this, props)` to ensure only setting props that exists)
		for (const [key, data] of Object.entries(props)) {
			// @ts-ignore
			if (this[key] !== undefined) this[key] = data;
		}
	}
}

export type CompCtxProps = Pick<InstanceType<typeof UseCompCtx>, "value" | "baseId" | "multiple" | "disabled" | "variant" | "size" | "rounded" | "onValueChange">;

export const setCompCtx = (props: CompCtxProps) => setContext(CONTEXT_ID, new UseCompCtx(props));

export const useCompCtx = () => getContext<ReturnType<typeof setCompCtx>>(CONTEXT_ID);

export type ItemCtxProps = Pick<InstanceType<typeof UseItemCtx>, "value" | "disabled">;

export const setItemCtx = (props: ItemCtxProps) => setContext(ITEM_CONTEXT_ID, new UseItemCtx(props));

export const useItemCtx = () => getContext<ReturnType<typeof setItemCtx>>(ITEM_CONTEXT_ID);

export { default as Accordion } from "./_.svelte";
export { default as AccordionItem } from "./item.svelte";
export { default as AccordionTrigger } from "./trigger.svelte";
export { default as AccordionContent } from "./content.svelte";

/** Accordion root that holds the open items and shares the style with its parts */
export interface Props extends CompPropsWithChild<"div"> {
	/** Values of the open items; supports `bind:value` */
	value?: string[];
	/** Items open at the start when `value` is not set */
	defaultValue?: string[];
	/** Called with the open values when an item opens or closes */
	onValueChange?: (value: string[]) => void;
	/** Lets several items be open at once; by default opening one closes the others */
	multiple?: boolean;
	/** Blocks opening and closing every item */
	disabled?: boolean;
	/** Visual style; `outline` wraps the items in a bordered box */
	variant?: "default" | "outline";
	/** Padding and text size on the shared scale; defaults to `md` */
	size?: UiSize;
	/** Corner radius of the box and focus rings; follows `size` when omitted. `pill` is a true pill that can clip the content, so use `3xl` or `4xl` to stay round */
	rounded?: UiRounded;
	/** Classes merged onto the accordion */
	class?: CompPropsWithChild<"div">["class"];
}

/** Section with a trigger and its collapsible content */
export interface ItemProps extends CompPropsWithChild<"div"> {
	/** Value that identifies the item in the open values */
	value: string;
	/** Blocks opening and closing the item; the arrow keys skip it */
	disabled?: boolean;
	/** Classes merged onto the item */
	class?: CompPropsWithChild<"div">["class"];
}

/** Props a custom trigger spreads onto the element that opens and closes its item */
export interface TriggerAttrs {
	/** Id that names the content */
	id: string;
	/** Whether the item is open */
	"aria-expanded": boolean;
	/** Id of the content */
	"aria-controls": string;
	/** Whether the item is disabled; the arrow keys skip it */
	disabled: boolean;
	/** `open` or `closed`, for styling */
	"data-state": "open" | "closed";
	/** Marks the element as a trigger that the up and down arrows move between */
	"data-accordion-trigger": true;
	/** Opens or closes the item */
	onclick: () => void;
	/** Moves focus between the triggers with the arrows, Home, and End */
	onkeydown: (e: KeyboardEvent) => void;
}

/** Heading button that opens and closes its item; renders a button with a chevron unless `trigger` is given */
export interface TriggerProps extends Omit<CompProps<"button">, "children"> {
	/** Label for the default trigger button */
	children?: Snippet;
	/** Custom trigger; spread `props` onto the element that opens and closes the item */
	trigger?: Snippet<[{ props: TriggerAttrs }]>;
	/** Classes merged onto the default trigger */
	class?: CompProps<"button">["class"];
}

/** Region shown while its item is open */
export interface ContentProps extends CompPropsWithChild<"div"> {
	/** Classes merged onto the content */
	class?: CompPropsWithChild<"div">["class"];
}

export type AccordionProps = Props;
export type AccordionItemProps = ItemProps;
export type AccordionTriggerProps = TriggerProps;
export type AccordionTriggerAttrs = TriggerAttrs;
export type AccordionContentProps = ContentProps;
